(window.CONTENT_LOADED=window.CONTENT_LOADED||{})["usluga/umowa-o-roboty-budowlane"]={"h1Full":"Umowa o roboty budowlane: kary, terminy, odbiory i zabezpieczenie zapłaty","topic":"Umowa o roboty budowlane","subtitle":"Firma budowlana dała Ci swoją umowę do podpisu i nie wiesz, czy chroni Cię przed opóźnieniem i fuszerką? Kara za zwłokę wykonawcy należy się tylko wtedy, gdy zastrzega ją umowa (art. 483 § 1 k.c.). Jako adwokat sprawdzam projekt umowy o roboty budowlane albo piszę ją od zera, zanim ją podpiszesz.","short":{"q":"Co powinna zawierać umowa z firmą budowlaną na budowę domu?","a":"Zakres robót z projektem, daty etapów i oddania, płatności po odbiorach, kary umowne, zasady usuwania wad i zgłaszania podwykonawców. Jeżeli umowa nie stanowi inaczej, na żądanie wykonawcy odbierasz roboty częściowo i płacisz za nie odpowiednią część wynagrodzenia (art. 654 k.c.).","facts":[["Forma","Pisemna; umowa zawarta ustnie nie jest przez to nieważna (art. 648 § 1, art. 73 § 1 k.c.)"],["Kara umowna","Tylko gdy zastrzega ją umowa i tylko za obowiązek niepieniężny, np. oddanie obiektu w terminie (art. 483 § 1 k.c.)"],["Podwykonawcy","Jeżeli roboty podwykonawcy zgłoszono Ci na piśmie przed ich rozpoczęciem, odpowiadasz solidarnie za jego wynagrodzenie. Zwalnia Cię pisemny sprzeciw do niego i wykonawcy w 30 dni od doręczenia zgłoszenia lub krótszym terminie z umowy (art. 647¹ § 1, § 1¹, § 4 k.c.)"],["Gwarancja zapłaty","Wykonawca może jej żądać w każdym czasie; przy umowie zawieranej dziś Kodeks wyłącza tylko inwestora, którym jest Skarb Państwa (art. 649¹ § 1¹, art. 649³ § 1 k.c.)"]]},"introHeading":"Umowa z firmą budowlaną: co daje ustawa, a co musisz wpisać sam","intro":"Kodeks dzieli obowiązki stron tej umowy (art. 647 k.c.). Wykonawca ma oddać obiekt opisany w umowie, wykonany według projektu i zasad wiedzy technicznej. Ty jako inwestor przekazujesz teren budowy i projekt, potem odbierasz obiekt i płacisz wynagrodzenie. Kodeks nie ustali za Ciebie daty oddania, kar ani zasad zaliczki. W umowach, które inwestorzy dostają od wykonawców, najczęściej brakuje kar umownych, dat etapów i zabezpieczenia na usterki.","whenTitle":"Czy to Twoja sytuacja","whenHeading":"Podpisujesz umowę o budowę lub remont jako inwestor albo wykonawca","when":[{"b":"Wykonawca czeka na podpis i chce zaliczki przed wejściem na budowę.","t":"Kodeks wiąże zapłatę z odbiorem robót, także częściowym (art. 647, art. 654 k.c.). Przepisy o tej umowie zaliczki nie przewidują, więc jej zasady ustalasz w umowie (art. 353¹ k.c.)."},{"b":"W umowie od firmy nie ma kar za spóźnienie, są za to kary dla Ciebie.","t":"Kary za spóźnioną zapłatę zastrzec nie można, bo zapłata to świadczenie pieniężne (art. 483 § 1 k.c.); wykonawcy należą się wtedy odsetki (art. 481 § 1 k.c.). Kara za Twoje obowiązki niepieniężne, np. przekazanie terenu budowy albo odbiór, jest dopuszczalna (art. 647 k.c.)."},{"b":"Remontujesz dom i nie wiesz, czy to umowa o roboty budowlane.","t":"Do umowy o remont budynku lub budowli stosuje się odpowiednio te same przepisy (art. 658 k.c.)."},{"b":"Jesteś wykonawcą, a inwestor nie chce słyszeć o zabezpieczeniu zapłaty.","t":"Prawa do żądania gwarancji zapłaty umowa nie wyłączy ani nie ograniczy (art. 649² § 1 k.c.)."}],"doForTitle":"Co sprawdzam i co dopisuję w umowie z wykonawcą","doFor":["Wpisuję kary za zwłokę w oddaniu etapów i obiektu oraz w usunięciu wad, z kwotą za dzień i limitem, a osobno wyliczam okoliczności, które wykonawcy nie usprawiedliwiają. Dopisuję prawo do odszkodowania ponad karę.","Wiążę płatności z odbiorami częściowymi, zostawiam część wynagrodzenia na usterki (kaucja, kwota zatrzymana albo gwarancja bankowa) i opisuję warunki zwrotu zaliczki.","Ustalam protokół odbioru, zgłaszanie wad oraz pisemne zgłaszanie podwykonawców z dowodem zapłaty im przed kolejną płatnością dla wykonawcy.","Ustalam ryczałt albo kosztorys i pisemne zlecanie robót dodatkowych z ceną. Wykonawcy przygotowuję harmonogram płatności i żądanie gwarancji zapłaty."],"lists":[{"eyebrow":"Porównanie","title":"Budowa domu: roboty budowlane czy dzieło – czym się różnią te umowy","kind":"check","items":[{"b":"Która to umowa","t":"liczy się zgodny zamiar stron i cel umowy, a nie samo jej brzmienie, np. tytuł (art. 65 § 2 k.c.). Przy robotach budowlanych wykonawca oddaje obiekt wykonany zgodnie z projektem (art. 647 k.c.), przy dziele wykonuje oznaczone dzieło (art. 627 k.c.)."},{"b":"Przedawnienie","t":"roboty budowlane: zasady ogólne (art. 118 k.c.); dzieło: 2 lata od oddania (art. 646 k.c.)."},{"b":"Podwykonawcy i gwarancja zapłaty","t":"przepisy tylko przy robotach budowlanych (art. 647¹, art. 649¹–649⁵ k.c.)."}]}],"stepsHeading":"Jak przygotowujemy umowę z wykonawcą przed podpisem","steps":["Przesyłasz projekt umowy albo ofertę wykonawcy i piszesz, na kiedy jest podpis i ile wynosi zaliczka.","W 24 h roboczych odpisuję, czy wystarczą poprawki do projektu wykonawcy, czy potrzebna jest nowa umowa. W tej samej odpowiedzi dostajesz ofertę.","Po akceptacji odsyłam umowę z poprawkami i komentarzem. Jeżeli wykonawca je odrzuca, wskazuję te, bez których zostajesz bez kar albo zwrotu zaliczki.","Podpis i przelew zaliczki robisz dopiero na wersji ostatecznej, bo od podpisu wiąże Cię treść umowy."],"faq":[{"q":"Jakie kary umowne wpisać w umowie z firmą budowlaną?","a":"Za zwłokę w oddaniu obiektu i etapów oraz w usunięciu wad, jako kwotę za dzień z górnym limitem. Kara należy się bez względu na wysokość szkody (art. 484 § 1 k.c.). Odszkodowania ponad karę możesz żądać tylko wtedy, gdy umowa na to pozwala. Rażąco wygórowanej kary wykonawca może żądać zmniejszenia (art. 484 § 2 k.c.)."},{"q":"Kiedy przedawniają się roszczenia z umowy o roboty budowlane?","a":"Co do zasady po 6 latach (art. 118 k.c.). Roszczenie związane z działalnością gospodarczą, np. firmy o wynagrodzenie, przedawnia się po 3 latach. Termin kończy się ostatniego dnia roku kalendarzowego. Dwa lata od oddania (art. 646 k.c.) dotyczą umowy o dzieło. Art. 656 § 1 k.c. nie odsyła do tego przepisu."},{"q":"Czy umowa o roboty budowlane musi być na piśmie?","a":"Powinna (art. 648 § 1 k.c.), ale umowa zawarta ustnie nie jest przez to nieważna (art. 73 § 1 k.c.). Pismo porządkuje zakres robót, bo wymagana przepisami dokumentacja jest częścią umowy (art. 648 § 2 k.c.). W razie wątpliwości przyjmuje się, że wykonawca podjął się wszystkich robót z projektu (art. 649 k.c.)."},{"q":"Jak zabezpieczyć zaliczkę dla wykonawcy?","a":"Wpisz do umowy kwotę zaliczki, jej cel, datę wejścia na budowę i termin zwrotu, jeżeli roboty nie ruszą. Jeżeli zaliczka to dla Ciebie duża kwota, wpisz też, że wypłacasz ją po otrzymaniu gwarancji bankowej lub ubezpieczeniowej jej zwrotu. Bez takiego zapisu nie możesz jej żądać: Kodeks daje prawo żądania gwarancji tylko wykonawcy (art. 649³ § 1 k.c.)."}],"law":{"asOf":"2026-10-10","items":[{"ref":"art. 647, art. 647¹ § 1, § 1¹ i § 4, art. 648, art. 649, art. 649¹ § 1¹, art. 649², art. 649³ § 1, art. 654, art. 656 § 1, art. 658","act":"Ustawa z dnia 23 kwietnia 1964 r. – Kodeks cywilny","tj":"Dz.U. 2026 poz. 795","eli":"DU/1964/93","note":"Umowa o roboty budowlane: definicja, podwykonawcy, forma, zakres robót, gwarancja zapłaty, odbiory częściowe, odesłanie do przepisów o dziele, remont."},{"ref":"art. 627, art. 646","act":"Ustawa z dnia 23 kwietnia 1964 r. – Kodeks cywilny","tj":"Dz.U. 2026 poz. 795","eli":"DU/1964/93","note":"Umowa o dzieło: definicja i przedawnienie roszczeń."},{"ref":"art. 65 § 2, art. 73 § 1, art. 118, art. 353¹, art. 455, art. 481 § 1, art. 483 § 1, art. 484","act":"Ustawa z dnia 23 kwietnia 1964 r. – Kodeks cywilny","tj":"Dz.U. 2026 poz. 795","eli":"DU/1964/93","note":"Wykładnia umowy, forma, przedawnienie, swoboda umów, termin świadczenia, odsetki, kara umowna."}]},"docs":["Projekt umowy albo ofertę wykonawcy z kosztorysem.","Planowane daty rozpoczęcia, etapów i oddania (wystarczy opis w formularzu).","Projekt budowlany albo opis robót, jeśli masz.","Kwotę zaliczki i harmonogram płatności, jeśli masz."],"seeAlso":["obsluga-prawna-firm-budowlanych","obsluga-prawna-architektow"],"cta":{"heading":"Dobra umowa to Twoja polisa na czas budowy.","lead":"Prześlij projekt umowy z firmą budowlaną albo jej ofertę. W 24 h roboczych odpiszę, którą drogę proponuję, i dołączę ofertę z ceną i terminem. Do jej akceptacji nic nie płacisz."}};
